"use client";import {useState} from 'react';import {supabaseBrowser} from '@/lib/supabase/browser';export default function Register(){const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[name,setName]=useState(''),[message,setMessage]=useState('');async function submit(e:React.FormEvent){e.preventDefault();const {error}=await supabaseBrowser().auth.signUp({email,password,options:{data:{full_name:name}}});setMessage(error?.message||'Pendaftaran diterima. Periksa email untuk verifikasi jika diaktifkan.')}return <div className="panel max-w-md"><h1>Daftar siswa</h1><form onSubmit={submit}><label>Nama</label><input required value={name} onChange={e=>setName(e.target.value)}/><label>Email</label><input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/><label>Password (min. 8 karakter)</label><input type="password" minLength={8} required value={password} onChange={e=>setPassword(e.target.value)}/><button className="mt-4">Daftar</button></form><p className="mt-3">{message}</p></div>}